using System;using System.Linq;using Mono.Cecil;class VerifyPatch {static void Main(string[] a){using(var x=AssemblyDefinition.ReadAssembly(a[0])){int n=0;foreach(var t in x.MainModule.Types)foreach(var m in t.Methods){if(!m.HasBody)continue;foreach(var i in m.Body.Instructions){var mr=i.Operand as MethodReference;if(mr!=null&&mr.DeclaringType.FullName=="TCG.NativeCompatibility.NativeToolPaths"&&(mr.Name=="Combine"||mr.Name=="FileManager"))n++;}}if(n!=6)throw new Exception("Expected6 scoped macOS helper dispatches; found "+n);Console.WriteLine("6 scoped dispatches verified");}}}
